function makeUserMessage(name, age) {
  const normalizedName = name ?? '손님';
  const normalizedAge = Number(age);
  const adult = normalizedAge >= 19;
  return `${normalizedName} / ${normalizedAge}세 / 성인 여부: ${adult}`;
}
